import requests

BASE_URL = "https://api.socbench.example"
ASSESSMENT_ID = "YOUR_ASSESSMENT_ID"
NEW_STATUS = "YOUR_NEW_STATUS"

session = requests.Session()
session.headers.update({"Accept": "application/json"})

report = {}

try:
    response = session.get(f"{BASE_URL}/inventory-overview")
    response.raise_for_status()
    report["inventory_overview"] = response.json()
except requests.RequestException as exc:
    report["inventory_overview_error"] = str(exc)

try:
    response = session.get(f"{BASE_URL}/transport-routes")
    response.raise_for_status()
    report["recommended_transport_routes"] = response.json()
except requests.RequestException as exc:
    report["transport_routes_error"] = str(exc)

try:
    response = session.get(f"{BASE_URL}/materials")
    response.raise_for_status()
    report["available_materials_and_specifications"] = response.json()
except requests.RequestException as exc:
    report["materials_error"] = str(exc)

try:
    response = session.patch(
        f"{BASE_URL}/impact-assessment/{ASSESSMENT_ID}/status",
        json={"status": NEW_STATUS},
    )
    response.raise_for_status()
    report["assessment_status_update"] = response.json() if response.content else {
        "status_code": response.status_code
    }
except requests.RequestException as exc:
    report["assessment_status_update_error"] = str(exc)

print(report)

